<?php $data=$_SESSION['reportData']??[];unset($_SESSION['reportData']);?><form action="<?=APP_URL?>/reports/create" method="post" class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div class="grid gap-5 md:grid-cols-2"><label class="text-sm font-medium">Submitted by<select name="submitted_by" required class="mt-2 w-full rounded-lg border border-slate-300 p-2.5"><option value="">Select</option><?php foreach($staff as $s):?><option value="<?=(int)$s['staff_id']?>" <?=(string)($data['submitted_by']??'')===(string)$s['staff_id']?'selected':''?>><?=e($s['full_name'])?></option><?php endforeach;?></select></label><label class="text-sm font-medium">Report type<select name="report_type" class="mt-2 w-full rounded-lg border border-slate-300 p-2.5"><?php foreach(['Monthly','Quarterly','Annual','Special'] as $v):?><option <?=($data['report_type']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><?php foreach([['reporting_period_start','Period start'],['reporting_period_end','Period end'],['submitted_date','Submitted date']] as [$n,$l]):?><label class="text-sm font-medium"><?=e($l)?><input type="date" name="<?=e($n)?>" required value="<?=e($data[$n]??'')?>" class="mt-2 w-full rounded-lg border border-slate-300 p-2.5"></label><?php endforeach;?><label class="text-sm font-medium">Version<input name="report_version" value="<?=e($data['report_version']??'1.0')?>" class="mt-2 w-full rounded-lg border border-slate-300 p-2.5"></label><label class="md:col-span-2"><input type="checkbox" name="generated_by_system" value="1" <?=!isset($data['generated_by_system'])||!empty($data['generated_by_system'])?'checked':''?>> Generated by system</label><label class="text-sm font-medium md:col-span-2">Remarks<textarea name="remarks" rows="4" class="mt-2 w-full rounded-lg border border-slate-300 p-2.5"><?=e($data['remarks']??'')?></textarea></label></div><div class="mt-6 flex gap-3"><button class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Submit Report</button><a href="<?=APP_URL?>/reports" class="rounded-lg border border-slate-300 px-4 py-2.5 text-sm">Cancel</a></div></form>
